package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.regex.*;
/** Static/synthetic contracts only. No capture, native source, device or input. */
public class NativeProgressLayoutWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java"));}
 private String between(String s,String a,String b){return s.substring(s.indexOf(a),s.indexOf(b,s.indexOf(a)));}
 @Test public void oneCompiledEntryOneCaptureNoExternalScope(){assertEquals(12,ReadOnlyCheckpoint.values().length);assertSame(ReadOnlyCheckpoint.UI_BOUND_POINTS_V53,ReadOnlyCheckpoint.CURRENT);assertEquals(1794466200000L,ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.starts());assertEquals(1794474000000L,ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.expires());assertTrue(ReadOnlyCheckpoint.CURRENT.validIndex(1));assertFalse(ReadOnlyCheckpoint.CURRENT.validIndex(0));assertFalse(ReadOnlyCheckpoint.CURRENT.validIndex(2));assertEquals(-1,ReadOnlyCheckpoint.CURRENT.sourceTask());assertNotEquals(RootProgressReadScope.DIRECTORY,ReadOnlyCheckpoint.CURRENT.directory());assertNotEquals(RootProgressScanScope.DIRECTORY,ReadOnlyCheckpoint.CURRENT.directory());}
 @Test public void sourceAndDeadlinesStayIndependent(){var p=ReadOnlyCheckpoint.CURRENT;assertTrue(p.current(p.starts()));assertFalse(p.current(p.expires()));assertFalse(p.admissionCurrent(p.expires()-ReadOnlyCheckpoint.SESSION_TTL));assertEquals(181000,p.sessionDeadline(1000,p.starts()));assertEquals(91000,p.deadline(1000,p.starts(),181000));assertEquals(2000,p.deadline(1000,p.starts(),2000));}
 @Test public void singleFrameEntryRejectsAnyContinuation()throws Exception{String s=between(source("CaptureSessionRuntime"),"static CaptureSessionRuntime startCheckpointRead(","static RootReturnReadIntent approveProgressScan(");assertTrue(s.contains("index!=1||previous!=null"));assertTrue(s.contains("startReadInternal(a,intent,root,index,null)"));String v=between(source("VisibleCaptureAuthority"),"static Proof issueCheckpointFrame(","static RootReturnReadIntent issueProgressScanIntent(");assertTrue(v.contains("index!=1||previous!=null"));}
 @Test public void allPriorLiveStartsBlocked()throws Exception{Matcher m=Pattern.compile("(?m)^    static CaptureSessionRuntime (start\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("CaptureSessionRuntime"));int n=0;while(m.find()){if(m.group(1).equals("startCheckpointRead")||m.group(1).equals("startProgressLocate"))continue;assertTrue(m.group(1),m.group(2).contains("if(ReadOnlyCheckpoint.CURRENT!=null)throw"));n++;}assertTrue(n>=16);}
 @Test public void allPriorIssuersBlocked()throws Exception{
  Matcher m=Pattern.compile("static [\\w.<>]+ (issue\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("VisibleCaptureAuthority"));int n=0,alignment=0;
  while(m.find()){
   if(m.group(1).equals("issueAlignment")){alignment++;continue;} // Independently checked by UiImageAlignmentEntryTest.
   if(m.group(1).equals("issueCheckpointIntent")||m.group(1).equals("issueCheckpointFrame")||m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame"))continue;
   assertTrue(m.group(1),m.group(2).contains("if(ReadOnlyCheckpoint.CURRENT!=null)throw"));n++;
  }
  assertTrue(n>=21);assertEquals(1,alignment);
 }
 @Test public void producerUsesOriginalFullRowsInOneOwningCallback()throws Exception{String s=source("ReadOnlyTwoStageRun");assertTrue(s.contains("layoutDiagnostic?NativeProgressLayoutDiagnostics.observe(binding,binding,rows,w,h):null"));String r=source("CaptureSessionRuntime");assertTrue(r.contains("returnReadIntent.layoutDiagnostic()?ReadOnlyTwoStageRun.Capture.layoutDiagnostic("));assertTrue(r.contains("returnReadIntent.checkpoint().store("));}
 @Test public void layoutUsesTypedFinalPublicationNotBusinessCounter()throws Exception{String s=between(source("CaptureSessionRuntime"),"private void closeReturnReadOnOwner(){","static final class ReturnReadCompletion");assertTrue(s.contains("if(returnReadIntent.layoutDiagnostic())pendingProgressPublication=new NativeProgressPublication("));assertTrue(s.contains("readOnlyObservation.layout(),healthy"));assertFalse(s.contains("layout().summary("));assertTrue(source("NativeProgressPublication").contains("layoutMode?(layout==null?"));assertTrue(source("DormantCaptureConfirmationActivity").contains("returnReadReports.add(exact.finalizeProgressPublication(details))"));}
 @Test public void noContinuationMintedForCheckpoint()throws Exception{String s=source("CaptureSessionRuntime");assertTrue(s.contains("returnReadIndex<RootReturnReadScope.MAX_FRAMES&&returnReadIntent.checkpoint()==null?new ReturnReadCompletion(this):null"));String v=between(source("VisibleCaptureAuthority"),"static RootReturnReadIntent issueCheckpointIntent(","static Proof issueCheckpointFrame(");assertTrue(v.contains("approval.checkpoint=policy"));assertFalse(v.contains("approval.progressScan=true"));assertFalse(v.contains("approval.progressRead=true"));}
 @Test public void fixedBurnCannotOverwriteReceipt()throws Exception{String s=source("ReadOnlyCheckpoint");assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("dir.resolve(\"READ_1.burned\")"));for(String bad:new String[]{"TRUNCATE_EXISTING","getIntent(","System.getenv","parseScope","getSharedPreferences"})assertFalse(bad,s.contains(bad));assertTrue(s.contains("maxSwipe=0 maxTap=0 maxReturn=0 maxText=0"));}
 @Test public void onlyNewChoiceIsOfferedAndNoInputActorConstructed()throws Exception{String a=source("DormantCaptureConfirmationActivity");String c=a.substring(a.indexOf("private void showCaptureChoices()"));assertTrue(c.indexOf("ReadOnlyCheckpoint.CURRENT!=null")<c.indexOf("RootProgressScanScope.ACTIVE"));String start=between(a,"private void confirmCheckpointRead(){","private void confirmProgressScan(){");for(String bad:new String[]{"SwipeActor","TapActor","BackActor","NativeAutonomousCardRun","ReturnPermit"})assertFalse(bad,start.contains(bad));assertTrue(start.contains("startCheckpointRead"));}
}
